"""Serialize manually authored passage judgments. No verdict is inferred from source text."""
from pathlib import Path
import json,csv,datetime,re
ROOT=Path(__file__).resolve().parents[1]
SRC=ROOT.parents[2]/'source'
PK='MPL_91_019-058'
P='SA03_texts/pro/'+PK+'_transcription.tex'
K='SA03_texts/codex/K91-01_transcription.tex'
items=[]; entries=[]; reads=[]; events=[]
DATE='2026-11-19'
WHO='GPT-6 Astra Pro; effort inherited/not exposed; run SA03-part3/a'

def add(n,src,kind,scans,ranges,quote,statement,reconstruction,check,reason,overrides=None,file=P):
    src=[int(x) for x in src.split(',')] if src else []
    loc=[{'file':file,'start':a,'end':b} for a,b in ranges]
    ident=f'SA03-{n}'
    items.append(dict(id=ident,sources=[f'{PK}#{x}' for x in src],kind=kind,cote=91,scans=scans,lines=loc,his_words=quote,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
    overrides=overrides or {}
    for i,x in enumerate(src):
        verdict,why=overrides.get(x,('kept' if i==0 else 'merged into item '+str(n),reason))
        entries.append(dict(entry_id=f'{PK}#{x}',item_id=ident,verdict=verdict,reason=why))
        reads.append(dict(entry_id=f'{PK}#{x}',source_file=file,line_ranges='; '.join(f'{a}-{b}' for a,b in ranges),reason=why))
    events.append(dict(statement_id=ident,date=DATE,who=WHO,type='used and rechecked in this run' if file else 'carried as background without fault found',outcome='Textual attribution check only, not a proof: '+reason))

